    if m:
        wells.append(dict(id=m[1], src='D4', sec=cur, well=m[2], S_nM=num(m[3]), raw=num(m[4]), unit='uMps'))

# D5 Priya and D10 Ruth: 'Plate N | Assay:' sections, mAU/min slopes
