        if line.startswith('Plate') and 'Assay' in line:
            cur = line
        m = re.match(r'^([A-H]\d{2})\s+(DR-\d{4})\s+([\d×\.\^\-]+)\s*(?:nM)?\s+([\d\.]+)\s+([\d\.]+)\s*(\S*)\s*$', line)
