            wells.append(dict(id=m[2], src=key, sec=cur, well=m[1], S_nM=num(m[3]), raw=float(m[4]), unit='mAU'))

# D9 CSV (µM/min, S nM)
for line in docs['D9'].splitlines():
    if line.startswith('DR-'):
        parts = next(csv_row for csv_row in [line.split(',')])
        wells.append(dict(id=parts[0], src='D9', sec=parts[3], well=parts[2], S_nM=float(parts[5]), raw=float(parts[6]), unit='uMmin', qc=parts[8]))

# D7 raw export (µM/min)
for line in docs['D7'].splitlines():
    m = re.match(r'^(\d+)\s+(\w\d+)\s+(DR-\d{4})\s+([\d\.]+)\s+', line)
    if m:
        wells.append(dict(id=m[3], src='D7', sec='plate%s' % m[1], well=m[2], S_nM=None, raw=float(m[4]), unit='uMmin'))

# D12 Owen: [S] = X nM: rN value (DR-XXXX)
cur = None
for line in docs['D12'].splitlines():
    if line.startswith('Condition:'):
        cur = line
    m = re.match(r'\s*\[S\] = ([\d]+) nM: (r\d) ([\d\.]+) \((DR-\d{4})', line)
