# --- condition assignment by source section (SOP §4 corrections applied) ---
def cond_of(w):
    s, sec, wid = w['src'], w['sec'] or '', w['id']
    if s == 'D4':
        return {'Plate 7': 'C5', 'Plate 8': 'C3', 'Plate 4, 30': 'C2', 'Plate 5': 'C4'}[next(k for k in ['Plate 7','Plate 8','Plate 4, 30','Plate 5'] if sec.startswith(k))]
    if s == 'D5':
        return {'Plate 4 | Assay: 25C': 'C1', 'Plate 4 | Assay: 42C/pH8.0 vehicle': 'C3', 'Plate 3 | Assay: 42C': 'C5'}[next(k for k in ['Plate 4 | Assay: 25C','Plate 4 | Assay: 42C/pH8.0 vehicle','Plate 3 | Assay: 42C'] if sec.startswith(k))]
    if s == 'D10':
        return {'Plate 4 | Assay: 30C': 'C2', 'Plate 3 | Assay: 25C': 'C1', 'Plate 2 | Assay: 42C': 'C7', 'Plate 4 | Assay: 25C/pH9.0': 'C4'}[next(k for k in ['Plate 4 | Assay: 30C','Plate 3 | Assay: 25C','Plate 2 | Assay: 42C','Plate 4 | Assay: 25C/pH9.0'] if sec.startswith(k))]
    if s == 'D9':
        # Pavel's own correction (2031-05-31 11:13): plate 1 row A is pH 8.0, 42 °C, no inhibitor = C3
        if wid in [f'DR-{n:04d}' for n in range(225, 234)]: return 'C3'
        if wid in [f'DR-{n:04d}' for n in range(247, 256)] or wid in [f'DR-{n:04d}' for n in range(519, 528)]: return 'C2'
        if wid in [f'DR-{n:04d}' for n in range(420, 429)]: return 'C7'
        raise SystemExit('unmapped D9 '+wid)
    if s == 'D12':
        return {'25C/pH9.0 vehicle': 'C4', '42C/pH8.5': 'C7', '25C/pH9.0, olvarin': 'C6', '42C/pH8.0 -inh': 'C3'}[next(k for k in ['25C/pH9.0 vehicle','42C/pH8.5','25C/pH9.0, olvarin','42C/pH8.0 -inh'] if sec.split(':',1)[1].strip().startswith(k))]
    if s == 'D7':
        return None
    raise SystemExit('?')

# --- unit conversion to µM/s (SOP header / notebook units) ---
def to_uMs(w):
    u = w['unit']
    if u == 'uMps': return w['raw']
    if u == 'uMmin': return w['raw'] / 60
    if u == 'mAU': return w['raw'] * MAP / 60
    raise SystemExit(u)

