    if w['src'] == 'D7':
        continue
    c = cond_of(w)
    rows[w['id']] = dict(id=w['id'], cond=c, S=(w['S_nM']/1000 if w['S_nM'] is not None else None), v=to_uMs(w), src=w['src'])

