d8_c6r1 = {'DR-0321':(8,1330),'DR-0322':(120,1.673e4),'DR-0323':(250,2.393e4),'DR-0324':(800,4.111e4),'DR-0325':(15,2387),'DR-0326':(25,3775),'DR-0327':(80,1.092e4),'DR-0328':(400,3.150e4),'DR-0329':(40,5859)}
