import json, math, sys
D = json.load(open(sys.argv[1]))
rows, excl = D['rows'], D['excl']
kept = [r for k,r in sorted(rows.items()) if k not in excl]

def sse_fixed_vmax(pts, km, vmax):
    return sum((v - vmax*s/(km+s))**2 for s,v in pts)

def best_vmax(pts, km):
    num = sum(v*s/(km+s) for s,v in pts)
    den = sum((s/(km+s))**2 for s,v in pts)
    return num/den

def sse_free(pts, km):
    return sse_fixed_vmax(pts, km, best_vmax(pts, km))

def minimize_km(f):
    lo, hi = math.log(1e-3), math.log(1e6)
    # coarse grid then golden refine
    grid = [lo + (hi-lo)*i/4000 for i in range(4001)]
    best = min(grid, key=lambda x: f(math.exp(x)))
    a, b = best-0.01, best+0.01
    g = (math.sqrt(5)-1)/2
    for _ in range(200):
        c, d = b-g*(b-a), a+g*(b-a)
        if f(math.exp(c)) < f(math.exp(d)): b = d
        else: a = c
    return math.exp((a+b)/2)

out = {}
for cond in ['C1','C2','C3','C4','C7']:
    pts = [(r['S'], r['v']) for r in kept if r['cond']==cond]
    km = minimize_km(lambda k: sse_free(pts, k))
    vmax = best_vmax(pts, km)
    out[cond] = dict(vmax=vmax, km=km, n=len(pts), sse=sse_free(pts,km))
    print(cond, 'n=',len(pts), 'Vmax=%.5f'%vmax, 'Km=%.3f'%km, 'SSE=%.5f'%out[cond]['sse'])

